.world-vignette { position: absolute; inset: 0; z-index: -1; pointer-events: none; background: linear-gradient(90deg, rgba(5,15,19,.83) 0%, rgba(5,15,19,.69) 31%, rgba(5,15,19,.14) 68%, rgba(5,15,19,.14) 100%), linear-gradient(0deg, rgba(3,13,16,.47), transparent 37%, rgba(3,13,16,.36)); }
.hidden { display: none !important; }

.topbar { position: absolute; top: 0; left: 0; right: 0; height: 82px; padding: 0 clamp(24px, 5vw, 82px); display: flex; align-items: center; justify-content: space-between; z-index: 4; border-bottom: 1px solid rgba(226,245,239,.08); background: linear-gradient(180deg, rgba(4,14,18,.64), rgba(4,14,18,.04)); }
