.top-center i { width: 1px; height: 14px; background: rgba(222,239,236,.28); }
.live-dot { width: 6px; height: 6px; background: var(--accent); border-radius: 50%; box-shadow: 0 0 11px var(--accent); }
.wallet { display: flex; align-items: center; gap: 8px; padding: 10px 13px; border: 1px solid rgba(226,245,239,.16); border-radius: 4px; background: rgba(4,14,18,.54); font-family: 'Barlow Condensed', sans-serif; font-size: 18px; font-weight: 800; }
.coin-icon, .wallet .coin-icon { color: var(--accent); font-size: 14px; }
