.menu-screen { position: absolute; inset: 82px clamp(24px, 5vw, 82px) 25px; z-index: 2; display: grid; grid-template-columns: minmax(330px, 430px) minmax(300px, 370px); grid-template-rows: minmax(175px, 1fr) auto auto; grid-template-areas: 'hero blank' 'garage track' 'footer start'; column-gap: clamp(18px, 3vw, 48px); row-gap: 13px; align-content: stretch; pointer-events: none; }
