.track-card:hover { background: rgba(236,247,244,.08); }
.track-card.selected { border-color: color-mix(in srgb, var(--track-accent), transparent 25%); background: color-mix(in srgb, var(--track-accent), transparent 91%); box-shadow: inset 3px 0 var(--track-accent); }
.track-icon { display: grid; place-items: center; width: 29px; height: 29px; flex: 0 0 29px; border-radius: 3px; color: var(--track-accent); background: color-mix(in srgb, var(--track-accent), transparent 89%); font-size: 17px; }
