.start-row { grid-area: start; align-self: start; display: flex; align-items: center; gap: 13px; animation: rise-in .7s .2s both; }
.start-btn { min-height: 47px; display: flex; flex: 1; align-items: center; justify-content: space-between; gap: 24px; padding: 0 15px 0 17px; background: var(--accent); color: #111a16; font-family: 'Barlow Condensed', sans-serif; font-size: 16px; font-weight: 900; letter-spacing: 1.5px; text-align: left; box-shadow: 0 6px 24px rgba(201,255,87,.16); transition: transform .18s ease, box-shadow .18s ease; }
