.menu-footer { grid-area: footer; align-self: center; display: flex; justify-content: space-between; gap: 9px; color: rgba(202,219,215,.64); font-size: 7px; font-weight: 800; letter-spacing: 1px; }
.menu-footer i { color: var(--accent); font-style: normal; padding: 0 3px; }

.race-hud { position: absolute; inset: 0; z-index: 3; pointer-events: none; }
.hud-card { position: absolute; top: max(95px, env(safe-area-inset-top)); min-width: 91px; padding: 10px 14px; border: 1px solid rgba(230,246,242,.16); border-radius: 3px; background: rgba(5,17,21,.58); backdrop-filter: blur(8px); }
.race-top-left { left: clamp(18px, 4vw, 58px); }
