.hud-coins { color: var(--accent); font-size: 23px !important; padding-top: 5px; }
.race-top-center { position: absolute; top: max(96px, env(safe-area-inset-top)); left: 50%; width: min(250px, 40vw); transform: translateX(-50%); text-align: center; }
.race-track-name { color: #eff8f4; font-family: 'Barlow Condensed', sans-serif; font-weight: 800; font-size: 14px; letter-spacing: 2px; text-shadow: 0 2px 6px #000; }
.lap-readout { margin-top: 5px; color: #c1d0cc; font-size: 8px; font-weight: 800; letter-spacing: 1.5px; }
.lap-readout b { margin-left: 3px; color: var(--accent); font-family: 'Barlow Condensed', sans-serif; font-size: 16px; }
.lap-readout > span { color: #829394; }
.lap-bar { height: 3px; margin-top: 7px; border-radius: 4px; background: rgba(231,245,240,.3); overflow: hidden; }
.lap-bar i { display: block; width: 0; height: 100%; background: var(--accent); box-shadow: 0 0 8px var(--accent); }
.speed-card { position: absolute; right: clamp(23px, 5vw, 74px); bottom: max(35px, env(safe-area-inset-bottom)); width: 126px; padding: 12px 14px 10px; border: 1px solid rgba(226,245,239,.16); background: rgba(5,17,21,.59); text-align: right; backdrop-filter: blur(7px); }
